namespace Decont;
public record PostingResult(string Version,List<string[]> Rows);
public sealed class Posting {
 public static readonly string[] Headers=["Date","Account type","Account","Business unit","Cost center","Objective","Site","Local account","Production line","Project","Sub account","Worker","Description","Debit","Credit","Currency","Sales Tax Group","Item sales tax group","Offset Account type","Offset account","Invoice nr","Invoice date","Document nr","Due date"];
 public PostingResult Build(Report report,User employee,List<Master> masters){
  Guard.Require(!string.IsNullOrWhiteSpace(employee.Worker),"worker","Configurează codul Worker al angajatului.","Configure the expense employee's Worker code.");List<string[]> rows=[];List<Master> used=[];
  Master Find(string kind,string code,DateOnly date){var m=masters.SingleOrDefault(m=>m.Kind==kind&&m.Code==code&&Rules.Effective(m,date));Guard.Require(m!=null,"mapping","Lipsește maparea: "+kind+" / "+code,"Mapping missing: "+kind+" / "+code);used.Add(m!);return m!;}
  string Required(Master m,string key){var value=Rules.Text(m,key);Guard.Require(value!="","mapping","Completează maparea: "+key,"Complete mapping: "+key);return value;}
  foreach(var line in report.Lines.Where(l=>!l.Archived).OrderBy(l=>l.Position)){
   var d=line.Data();var date=DateOnly.Parse(d.Date);var map=Find("accounting",d.Category,date);var settings=Find("erpSettings","default",date);Required(settings,"approvalReference");var gl=Required(map,"mainAccount");var local=Required(map,"localAccount");var sub=Rules.Text(map,"subAccount");var car=Rules.Data(map).TryGetProperty("vehicle",out var vehicle)&&vehicle.GetBoolean();var cc=Required(Find("costCenters",d.CostCenter,date),"erpCode");var project=string.IsNullOrEmpty(d.Project)?"":Required(Find("projects",d.Project,date),"erpCode");var clearing=Required(settings,"clearingAccount");var clearingLocal=Required(settings,"clearingLocal");
   string[] Row(string type,string account,decimal debit=0,decimal credit=0,string? localOverride=null,string? subOverride=null,string sales="",string tax="",string offsetType="",string offset="",bool invoice=false){var r=new string[24];Array.Fill(r,"");foreach(var pair in new[]{(0,"exportDate"),(3,"businessUnit"),(5,"objective"),(6,"site"),(8,"productionLine"),(15,"exportCurrency"),(22,"documentNumber"),(23,"dueDate")})r[pair.Item1]=Rules.Text(settings,pair.Item2).Replace("{{documentDate}}",d.Date).Replace("{{invoice}}",d.Invoice).Replace("{{reportNumber}}",report.Number);r[1]=type;r[2]=account;r[4]=type=="Vendor"?"":cc;r[7]=type=="Vendor"?"":localOverride??local;r[9]=project;r[10]=type=="Vendor"?"":subOverride??sub;r[11]=employee.Worker;r[12]=d.Description;r[13]=debit==0?"":Rules.Money(debit).ToString("0.00",System.Globalization.CultureInfo.InvariantCulture);r[14]=credit==0?"":Rules.Money(credit).ToString("0.00",System.Globalization.CultureInfo.InvariantCulture);r[16]=sales;r[17]=tax;r[18]=offsetType;r[19]=offset;if(invoice){r[20]=d.Invoice;r[21]=d.Date;}rows.Add(r);return r;}
   if(d.Country!="RO"||d.DocumentType!="InvoiceWithCui"){
    if(car&&d.Country!="RO"){var half=Rules.Money(line.Final()/2);Row("Ledger",gl,half,offsetType:"Ledger",offset:clearing);Row("Ledger",gl,line.Final()-half,subOverride:"",offsetType:"Ledger",offset:clearing);}else Row("Ledger",gl,line.Final(),offsetType:"Ledger",offset:clearing);continue;
   }
   var vendor=Required(Find("suppliers",Rules.Cui(d.Cui),date),"vendorAccount");decimal bases=0;bool vendorWritten=false;
   foreach(var tax in d.Taxes){var rate=masters.Single(m=>m.Id==tax.RateId&&m.Kind=="vat"&&Rules.Effective(m,date));used.Add(rate);var pct=Rules.Number(rate,"rate");Guard.Require(pct is 0 or 11 or 21,"vat","Cotă TVA ERP neacceptată.","Unsupported ERP VAT rate.");var sales=Required(rate,"salesTaxGroup");bases+=tax.Base;
    if(!car){Row("Ledger",gl,tax.Base,sales:sales,tax:Required(rate,"itemTaxGroup"));}
    else {var half=Rules.Money(tax.Base/2);Row("Ledger",gl,half,sales:sales,tax:Required(rate,pct==0?"itemTaxGroup":"nonDeductible50Code"));Row("Ledger",gl,tax.Base-half,subOverride:"",sales:sales,tax:Required(rate,pct==0?"itemTaxGroup":"deductible50Code"));
     if(d.Taxes.Count==1){Row("Vendor",vendor,credit:tax.Base,invoice:true);vendorWritten=true;}if(pct>0){var repair=Rules.Data(map).TryGetProperty("repair",out var rp)&&rp.GetBoolean();var nonDedAccount=Required(settings,repair?"repairNonDedAccount":"otherCarNonDedAccount");var nonDedLocal=repair?Required(settings,"repairNonDedLocal"):local;var halfVat=Rules.Money(tax.Vat/2);var quarter=Rules.Money(tax.Vat/4);Row("Ledger",nonDedAccount,quarter,localOverride:nonDedLocal);Row("Ledger",nonDedAccount,halfVat-quarter,localOverride:nonDedLocal,subOverride:"");Row("Ledger",Required(settings,"vatAccount"),credit:halfVat,localOverride:Required(settings,"vatLocal"));}
    }
   }
   if(!vendorWritten)Row("Vendor",vendor,credit:bases,invoice:true);Row("Ledger",clearing,credit:line.Final(),localOverride:clearingLocal,subOverride:"",offsetType:"Vendor",offset:vendor);
  }
  Guard.Require(rows.Count>0&&rows.All(r=>r.Length==24&&!string.IsNullOrWhiteSpace(r[2])),"schema","Export ERP invalid.","Invalid ERP export.");var version=Serialization.Hash(Serialization.Write(used.DistinctBy(m=>m.Id).OrderBy(m=>m.Id).Select(m=>new{m.Id,m.Json,m.From,m.To})));return new(version,rows);
 }
}
